import logging
import re
from pathlib import Path

from ...common import XMLReader, read_xml, save_xml
from ...llm import LLM
from ...pdf import TITLE_TAGS, Page
from ...pdf import decode as decode_pdf
from .llm_analyser import (
    LLMAnalysisError,
    analyse_title_levels_by_llm,
    analyse_toc_levels_by_llm,
)
from .toc_levels import Ref2Level, analyse_title_levels, analyse_toc_levels
from .toc_pages import PageRef, find_toc_pages
from .types import Toc, TocInfo
from .types import decode as decode_toc
from .types import encode as encode_toc

logger = logging.getLogger(__name__)

_TITLE_HEAD_REGX = re.compile(r"^\s*#{1,6}\s*")


def analyse_toc(
    pages_path: Path,
    toc_path: Path,
    toc_assumed: bool,
    toc_llm: LLM | None = None,
) -> TocInfo:
    if toc_path.exists():
        return decode_toc(read_xml(toc_path))

    toc_path.parent.mkdir(parents=True, exist_ok=True)
    toc_info = _do_analyse_toc(pages_path, toc_llm, toc_assumed)
    save_xml(encode_toc(toc_info), toc_path)

    return toc_info


def _do_analyse_toc(
    pages_path: Path,
    toc_llm: LLM | None,
    toc_assumed: bool,
) -> TocInfo:
    pages: XMLReader[Page] = XMLReader(
        prefix="page",
        dir_path=pages_path,
        decode=decode_pdf,
    )
    toc_pages: list[PageRef] = []
    if toc_assumed:
        toc_pages = find_toc_pages(
            iter_titles=lambda: (
                list(
                    (layout.order, _TITLE_HEAD_REGX.sub("", layout.text))
                    for layout in page.body_layouts
                    if layout.ref in TITLE_TAGS
                )
                for page in pages.read()
            ),
            iter_page_bodies=lambda: (
                "".join(layout.text for layout in page.body_layouts)
                for page in pages.read()
            ),
        )

    ref2level: Ref2Level | None = None
    toc_page_indexes: list[int] = []

    if toc_pages:
        if toc_llm is not None:
            try:
                ref2level = analyse_toc_levels_by_llm(
                    llm=toc_llm,
                    toc_page_refs=toc_pages,
                    toc_page_contents=list(
                        pages.read(
                            page_indexes={
                                toc_page.page_index for toc_page in toc_pages
                            },
                        )
                    ),
                )
            except LLMAnalysisError as error:
                print(
                    f"LLM analysis toc failed, falling back to statistical method: {error}"
                )

        if ref2level is None:
            ref2level = analyse_toc_levels(
                pages=pages,
                pages_path=pages_path,
                toc_pages=toc_pages,
            )
        toc_page_indexes.extend(ref.page_index for ref in toc_pages)
        toc_page_indexes.sort()

    else:
        if toc_llm is not None:
            try:
                ref2level = analyse_title_levels_by_llm(toc_llm, pages)
            except LLMAnalysisError as error:
                print(
                    f"LLM analysis title failed, falling back to statistical method: {error}"
                )

        if ref2level is None:
            ref2level = analyse_title_levels(pages)

    return TocInfo(
        content=_structure_toc_by_levels(ref2level),
        page_indexes=toc_page_indexes,
    )


def _structure_toc_by_levels(ref2level: Ref2Level) -> list[Toc]:
    # virtual root
    root = Toc(
        id=-1,
        page_index=-1,
        order=-1,
        level=-1,
        children=[],
    )
    next_id: int = 1
    stack: list[Toc] = [root]

    for (page_index, order), level in sorted(ref2level.items(), key=lambda x: x[0]):
        toc = Toc(
            id=next_id,
            page_index=page_index,
            order=order,
            level=level,
            children=[],
        )
        next_id += 1
        while stack and stack[-1].level >= level:
            stack.pop()

        if not stack:
            break

        stack[-1].children.append(toc)
        stack.append(toc)

    return root.children

from dataclasses import dataclass
from pathlib import Path

from ...common import XMLReader, avg, read_xml, split_by_cv
from .config import MAX_LEVELS, MAX_TITLE_CV
from ...pdf import TITLE_TAGS, Page, PageLayout
from ...pdf import decode as decode_as_page
from .text import normalize_text
from .toc_pages import PageRef

_MAX_TOC_CV = 0.75  # 不宜过小导致过多分组

Ref2Level = dict[tuple[int, int], int]  # key: (page_index, order) value: level


def analyse_title_levels(pages: XMLReader[Page]) -> Ref2Level:
    return _extract_content_title_levels(pages)


def analyse_toc_levels(
    pages: XMLReader[Page], pages_path: Path, toc_pages: list[PageRef]
) -> Ref2Level:
    ref2meta, toc_page_indexes = _extract_ref2meta(
        pages_path=pages_path,
        toc_pages=toc_pages,
    )
    ref2global_level = _extract_content_title_levels(
        pages=pages,
        disable_page_indexes=toc_page_indexes,
        ref2meta=ref2meta,
    )
    toc_level_offset = _extract_toc_level_offset(
        ref2meta=ref2meta,
        ref2level=ref2global_level,
    )
    ref2level: Ref2Level = {}
    for (page_index, order), meta in ref2meta.items():
        level_offset = toc_level_offset.get(meta.toc_page_index, None)
        if (
            level_offset is not None
        ):  # toc_level_offset 比 ref2meta 范围小，目录页子圈会被排除
            global_level = meta.relative_level + level_offset
            ref2level[(page_index, order)] = global_level

    return ref2level


@dataclass
class _Hook:
    layout: PageLayout
    references: list[tuple[int, int]]  # (page_index, order)


@dataclass
class _TitleMeta:
    toc_page_index: int
    relative_level: int
    collected_global_levels: list[int]


_Ref2Meta = dict[tuple[int, int], _TitleMeta]


def _extract_ref2meta(
    pages_path: Path, toc_pages: list[PageRef]
) -> tuple[_Ref2Meta, set[int]]:
    ref2meta: _Ref2Meta = {}  # key: (page_index, order)
    toc_page_indexes: set[int] = set()

    for ref in toc_pages:
        toc_page_indexes.add(ref.page_index)
        grouped_hooks = _analyse_toc_page_hooks(
            ref=ref,
            page_path=Path(pages_path / f"page_{ref.page_index}.xml"),
        )
        for level, hooks in enumerate(grouped_hooks):
            for hook in sorted(hooks, key=lambda x: x.layout.order):
                for page_index, order in hook.references:
                    if (page_index, order) not in ref2meta:
                        ref2meta[(page_index, order)] = _TitleMeta(
                            toc_page_index=ref.page_index,
                            relative_level=level,
                            collected_global_levels=[],
                        )
    return ref2meta, toc_page_indexes


def _analyse_toc_page_hooks(ref: PageRef, page_path: Path) -> list[list[_Hook]]:
    page = decode_as_page(read_xml(page_path))
    hooks_items: list[tuple[float, _Hook]] = []

    for layout in page.body_layouts:
        layout_text = normalize_text(layout.text)
        references_set: set[tuple[int, int]] = set()
        for title in ref.matched_titles:
            if title.text not in layout_text:
                continue
            for reference in title.references:
                references_set.add(
                    (
                        reference.page_index,
                        reference.order,
                    )
                )
        if not references_set:
            continue
        _, top, _, bottom = layout.det
        height = bottom - top
        hooks_items.append(
            (
                height,
                _Hook(
                    layout=layout,
                    references=list(references_set),
                ),
            )
        )
    hooks = split_by_cv(
        payload_items=hooks_items,
        max_groups=MAX_LEVELS,
        max_cv=_MAX_TOC_CV,
    )
    hooks.reverse()  # 字体最大的是 Level 0，故颠倒
    return hooks


def _extract_content_title_levels(
    pages: XMLReader[Page],
    disable_page_indexes: set[int] | None = None,
    ref2meta: _Ref2Meta | None = None,
) -> Ref2Level:
    title_items: list[tuple[float, tuple[int, int]]] = []
    for page in pages.read():
        if disable_page_indexes and page.index in disable_page_indexes:
            continue
        for layout in page.body_layouts:
            if layout.ref not in TITLE_TAGS:
                continue
            ref = (page.index, layout.order)
            if ref2meta and ref not in ref2meta:
                continue
            _, top, _, bottom = layout.det
            height = bottom - top
            title_items.append((height, ref))

    title2levels: Ref2Level = {}
    for level, refs in enumerate(
        reversed(
            split_by_cv(  # 字体最大的是 Level 0，故颠倒
                payload_items=title_items,
                max_groups=MAX_LEVELS,
                max_cv=MAX_TITLE_CV,
            )
        )
    ):
        for ref in refs:
            title2levels[ref] = level

    return title2levels


def _extract_toc_level_offset(
    ref2meta: _Ref2Meta, ref2level: Ref2Level
) -> dict[int, int]:
    # 目录可能有多页，每页自己的 Level 只能表示相对关系，这里计算出全局目录的 level
    for page_index, order in sorted(ref2level.keys()):
        meta = ref2meta[(page_index, order)]
        level = ref2level[(page_index, order)]
        meta.collected_global_levels.append(level)

    page2metas: dict[int, list[_TitleMeta]] = {}
    for meta in ref2meta.values():
        metas = page2metas.get(meta.toc_page_index, None)
        if metas is None:
            metas = []
            page2metas[meta.toc_page_index] = metas
        metas.append(meta)

    avg_level_items: list[tuple[float, int]] = []  # (avg_level, page_index)
    for page_index, metas in page2metas.items():
        metas.sort(key=lambda x: x.relative_level)
        meta = metas[0]
        levels = metas[0].collected_global_levels
        if levels:
            avg_level = avg(levels)
            avg_level_items.append((avg_level, page_index))

    toc_level_offset: dict[int, int] = {}
    for offset, page_indexes in enumerate(
        split_by_cv(
            payload_items=avg_level_items,
            max_groups=MAX_LEVELS,
            max_cv=_MAX_TOC_CV,
        )
    ):
        # 大多数情况下只有一组，便只有 offset=0 的情况。
        for page_index in page_indexes:
            toc_level_offset[page_index] = offset

    return toc_level_offset

import sys
from typing import Generic, TypeVar

P = TypeVar("P")


class _Group(Generic[P]):
    def __init__(self, items: list[tuple[float, P]]):
        self._items: list[tuple[float, P]] = items
        self._cached_cv: float | None = None
        self._cached_size: float | None = None

    @property
    def items(self) -> list[tuple[float, P]]:
        return self._items

    @property
    def cv(self) -> float:
        if self._cached_cv is None:
            self._cached_cv = self._calculate_cv(
                values=[size for size, _ in self._items],
            )
        return self._cached_cv

    @property
    def size(self) -> float:
        if self._cached_size is None:
            if self._items:
                self._cached_size = sum(size for size, _ in self._items) / len(
                    self._items
                )
            else:
                self._cached_size = 0.0
        return self._cached_size

    def _calculate_cv(self, values: list[float]) -> float:
        if not values or len(values) < 2:
            return 0.0
        mean = sum(values) / len(values)
        if mean == 0:
            return float("inf")
        variance = sum((x - mean) ** 2 for x in values) / len(values)
        std = variance**0.5
        return std / mean


def split_by_cv(
    payload_items: list[tuple[float, P]],
    max_cv: float = 0.0,
    max_groups: int = sys.maxsize,
) -> list[list[P]]:
    """通过控制 CV （变异系数）将 payload 分组，返回分组后的 payload 列表"""

    if len(payload_items) <= 2:
        return [[payload for _, payload in payload_items]]

    groups: list[_Group[P]] = [_Group(items=payload_items)]

    while len(groups) < max_groups:
        max_cv_group_index = _find_max_cv_group_index(groups, max_cv)
        if max_cv_group_index == -1:
            break

        splitted = _split_group_by_max_gap(groups[max_cv_group_index].items)
        if splitted is None:
            break

        group1_items, group2_items = splitted
        groups[max_cv_group_index] = _Group(items=group1_items)
        groups.insert(max_cv_group_index + 1, _Group(items=group2_items))

    return [
        [payload for _, payload in group.items]
        for group in sorted(groups, key=lambda g: g.size)
    ]


def _find_max_cv_group_index(
    groups: list[_Group[P]],
    max_cv: float,
) -> int:
    max_cv_group_index = -1
    max_cv_value = max_cv

    for i, group in enumerate(groups):
        if len(group.items) <= 2:
            continue

        if group.cv > max_cv_value:
            max_cv_value = group.cv
            max_cv_group_index = i

    return max_cv_group_index


def _split_group_by_max_gap(
    group: list[tuple[float, P]],
) -> tuple[list[tuple[float, P]], list[tuple[float, P]]] | None:
    sorted_items = sorted(group, key=lambda x: x[0])
    gaps: list[tuple[float, int]] = []

    for i in range(len(sorted_items) - 1):
        gap = sorted_items[i + 1][0] - sorted_items[i][0]
        gaps.append((gap, i))

    if not gaps:
        return None

    _, split_index = max(gaps, key=lambda x: x[0])
    group1 = sorted_items[: split_index + 1]
    group2 = sorted_items[split_index + 1 :]

    return group1, group2

from dataclasses import dataclass
from typing import Generator
from xml.etree.ElementTree import Element

from ...common import indent


@dataclass
class TocInfo:
    content: list["Toc"]
    page_indexes: list[int]


@dataclass
class Toc:
    id: int
    page_index: int
    order: int
    level: int
    children: list["Toc"]


def iter_toc(toc_list: list[Toc]) -> Generator[Toc, None, None]:
    for toc in toc_list:
        yield toc
        yield from iter_toc(toc.children)


def encode(toc_info: TocInfo) -> Element:
    root = Element("toc")
    page_indexes_str = ",".join(str(idx) for idx in toc_info.page_indexes)
    root.set("page_indexes", page_indexes_str)

    def encode_item(toc: Toc, parent: Element) -> None:
        item = Element("item")
        item.set("id", str(toc.id))
        item.set("page_index", str(toc.page_index))
        item.set("order", str(toc.order))
        item.set("level", str(toc.level))

        for child in toc.children:
            encode_item(child, item)
        parent.append(item)

    for toc in toc_info.content:
        encode_item(toc, root)
    return indent(root)


def decode(element: Element) -> TocInfo:
    if element.tag != "toc":
        raise ValueError(f"Expected root tag 'toc', got '{element.tag}'")

    page_indexes_str = element.get("page_indexes")
    if page_indexes_str is None:
        raise ValueError("Missing 'page_indexes' attribute in toc")

    page_indexes = []
    if page_indexes_str:
        page_indexes = [int(idx) for idx in page_indexes_str.split(",")]

    def decode_item(item: Element) -> Toc:
        if item.tag != "item":
            raise ValueError(f"Expected tag 'item', got '{item.tag}'")

        id_str = item.get("id")
        page_index_str = item.get("page_index")
        order_str = item.get("order")
        level_str = item.get("level")

        if id_str is None:
            raise ValueError("Missing 'id' attribute in item")
        if page_index_str is None:
            raise ValueError("Missing 'page_index' attribute in item")
        if order_str is None:
            raise ValueError("Missing 'order' attribute in item")
        if level_str is None:
            raise ValueError("Missing 'level' attribute in item")

        children = [decode_item(child) for child in item]

        return Toc(
            id=int(id_str),
            page_index=int(page_index_str),
            order=int(order_str),
            level=int(level_str),
            children=children,
        )

    return TocInfo(
        content=[decode_item(item) for item in element],
        page_indexes=page_indexes,
    )

import unittest
from typing import cast

from pdf_craft.llm.types import Message, MessageRole
from pdf_craft.llm.core import LLM
from pdf_craft.extractor.toc.llm_analyser import (
    LLMAnalysisError,
    _LLMAnalyser,
    _validate_title_response,
    _validate_toc_response,
)


class _BrokenLLM:
    def request(self, input):  # pylint: disable=redefined-builtin,unused-argument
        raise RuntimeError("blocked by upstream")


class _JsonLLM:
    def request(self, input):  # pylint: disable=redefined-builtin,unused-argument
        return '{"0": 0, "1": 1}'


class _SequenceLLM:
    def __init__(self, responses):
        self.responses = iter(responses)
        self.calls = 0

    def request(self, input):  # pylint: disable=redefined-builtin,unused-argument
        self.calls += 1
        return next(self.responses)


class _ResultLLM:
    def request(self, input):  # pylint: disable=redefined-builtin,unused-argument
        return 'ANALYSIS: example {"A": 99}\nRESULT: {"A": 0, "B": 1}\nRESULT: {"A": 2, "B": 3}'


class TestLLMAnalyser(unittest.TestCase):
    def test_wraps_llm_request_errors_as_analysis_error(self):
        analyser = _LLMAnalyser(
            llm=cast(LLM, _BrokenLLM()),
            validate=lambda response, payload: (response, None),  # pragma: no cover
        )

        with self.assertRaises(LLMAnalysisError) as context:
            analyser.request(
                payload=1,
                messages=(
                    Message(role=MessageRole.SYSTEM, message="system"),
                    Message(role=MessageRole.USER, message="user"),
                ),
            )

        self.assertIn("LLM request failed at attempt 1", str(context.exception))
        self.assertIsInstance(context.exception.__cause__, RuntimeError)

    def test_accepts_json_extracted_by_guaranteed_layer(self):
        analyser = _LLMAnalyser(
            llm=cast(LLM, _JsonLLM()),
            validate=lambda response, payload: ([0, 1], None)
            if response == '{"0": 0, "1": 1}' else (None, "unexpected response"),
        )
        self.assertEqual(
            analyser.request(payload=None, messages=[Message(MessageRole.USER, "json")]),
            [0, 1],
        )

    def test_non_object_response_is_schema_retry(self):
        llm = _SequenceLLM(["[1, 2]", '{"0": 0, "1": 1}'])
        analyser = _LLMAnalyser(
            llm=cast(LLM, llm),
            validate=lambda response, payload: ([0, 1], None),
        )
        self.assertEqual(analyser.request(payload=None, messages=[Message(MessageRole.USER, "json")]), [0, 1])
        self.assertEqual(llm.calls, 2)

    def test_non_object_response_exhausts_as_typed_schema_failure(self):
        llm = _SequenceLLM(["[1, 2]"] * 3)
        analyser = _LLMAnalyser(
